INSERT INTO "public"."categories" ("id", "parent_id", "name_translations", "description_translations", "slug", "image_url", "is_active", "order_rank", "created_at", "updated_at", "is_deleted") VALUES ('01b10c1b-6e22-4690-967f-326c0a33b09d', 'c3b9f610-7c2a-4316-a17b-dff4bba80183', '{"en": "Cabbages", "fr": "Choux"}', '{"en": "Discover Quebec cabbages, rich in flavor, perfect for salads and hearty dishes.", "fr": "Découvrez des choux du Québec, riches en saveur, parfaits pour salades et plats mijotés."}', '{"en": "cabbages", "fr": "choux"}', null, 'true', '0', '2025-04-26 11:01:28.451657+00', '2025-04-26 11:01:28.451657+00', 'false'), ('03c17a1e-c986-4e28-98f7-48ed583a861f', 'a875e1fd-cd61-424d-b489-4889fd3a4fef', '{"en": "Pet Food", "fr": "Nourriture pour animaux"}', '{"en": "Provide your pets with healthy food made in Quebec, tailored to their nutritional needs.", "fr": "Offrez à vos animaux une alimentation saine avec des produits québécois de qualité, adaptés à leurs besoins."}', '{"en": "pet-food", "fr": "nourriture-pour-animaux"}', null, 'true', '0', '2025-04-26 13:02:42.805304+00', '2025-04-26 13:02:42.805304+00', 'false'), ('0616ef2e-e679-459b-b599-653aae36a973', 'a875e1fd-cd61-424d-b489-4889fd3a4fef', '{"en": "Collars and Leashes", "fr": "Colliers et laisses"}', '{"en": "Discover sturdy and stylish Quebec-made collars and leashes for walking your pets safely and in style.", "fr": "Découvrez des colliers et laisses québécois robustes et élégants pour promener vos animaux en toute sécurité et avec style."}', '{"en": "collars-and-leashes", "fr": "colliers-et-laisses"}', null, 'true', '0', '2025-04-26 12:58:25.225622+00', '2025-04-26 12:58:25.225622+00', 'false'), ('06314e6b-bff6-4bb7-8b3f-b545d1f56df8', 'c3b9f610-7c2a-4316-a17b-dff4bba80183', '{"en": "Cucumbers", "fr": "Concombres"}', '{"en": "Refresh yourself with Quebec cucumbers, fresh, crunchy, and 100% locally grown.", "fr": "Rafraîchissez-vous avec des concombres du Québec, frais, croquants et 100% locaux."}', '{"en": "cucumbers", "fr": "concombres"}', null, 'true', '0', '2025-04-26 11:00:24.182848+00', '2025-04-26 11:00:24.182848+00', 'false'), ('06b6a1d1-0ecf-4ead-8b7b-a87f2937a569', '90bd2019-c6c2-4e43-82fa-71bb83f7e088', '{"en": "Natural and Organic Cosmetics", "fr": "Cosmétiques naturels et bio"}', '{"en": "Enhance your beauty with natural and organic cosmetics made in Quebec, respectful of your skin and the planet.", "fr": "Sublimez votre beauté avec des cosmétiques naturels et bio fabriqués au Québec, respectueux de votre peau et de la planète."}', '{"en": "natural-and-organic-cosmetics", "fr": "cosmetiques-naturels-et-bio"}', null, 'true', '0', '2025-04-26 14:13:34.319112+00', '2025-04-26 14:13:34.319112+00', 'false'), ('085f2897-d05d-4349-a4cb-ee6d56831bde', 'bf93ba14-4153-438b-b2f0-e500747f0110', '{"en": "Organic Coffee", "fr": "Cafés biologiques"}', '{"en": "Savor Quebec organic coffee, grown and roasted without pesticides for a pure taste.", "fr": "Savourez des cafés biologiques du Québec, cultivés et torréfiés sans pesticides pour un goût pur."}', '{"en": "organic-coffee", "fr": "cafes-biologiques"}', null, 'true', '0', '2025-04-26 11:19:48.304698+00', '2025-04-26 11:19:48.304698+00', 'false'), ('0d7fbf04-7ebb-46a7-9d45-7130d82b2669', '26097817-d298-416a-ac5b-362e5e4596ca', '{"en": "Maple Butter, Candy and Treats", "fr": "Beurre, bonbons et douceurs à l’érable"}', '{"en": "Experience Quebec’s finest maple treats including creamy maple butter, hard candies, fudge and handmade sweets made by local artisans.", "fr": "Retrouvez le meilleur du savoir-faire local avec du beurre d’érable crémeux, des bonbons durs, du fudge et autres douceurs faites maison au Québec."}', '{"en": "maple-butter-candy-and-treats", "fr": "beurre-bonbons-et-douceurs-a-lerable"}', null, 'true', '0', '2025-04-30 23:52:44.444874+00', '2025-04-30 23:52:44.444874+00', 'false'), ('0e1739e2-1cd9-4085-97dd-7840aa8f9d3f', 'a875e1fd-cd61-424d-b489-4889fd3a4fef', '{"en": "Organic Pet Food", "fr": "Nourriture pour animaux bio"}', '{"en": "Choose organic pet food, locally produced to support your pets'' health and respect the environment.", "fr": "Choisissez de la nourriture bio pour animaux, produite localement pour soutenir leur santé et respecter l''environnement."}', '{"en": "organic-pet-food", "fr": "nourriture-pour-animaux-bio"}', null, 'true', '0', '2025-04-26 13:03:12.959092+00', '2025-04-26 13:03:12.959092+00', 'false'), ('1eb1affd-ed32-435a-964c-fef51f302ee4', 'cd081c43-702a-45d7-82e6-1fc23f567915', '{"en": "Microbrewery Beers", "fr": "Bières de microbrasserie"}', '{"en": "Savor Quebec microbrewery beers, locally brewed with passion and creativity for original flavors.", "fr": "Savourez des bières de microbrasserie du Québec, brassées localement avec passion et créativité pour des goûts originaux."}', '{"en": "microbrewery-beers", "fr": "bieres-de-microbrasserie"}', null, 'true', '0', '2025-04-26 11:23:54.672468+00', '2025-04-26 11:23:54.672468+00', 'false'), ('229cd7fd-f9b4-45f3-9f2c-ae7e68ee2284', '4cd35b53-8ce2-4733-9087-8f4d263e9469', '{"en": "Apples", "fr": "Pommes"}', '{"en": "Discover local Quebec apples, carefully grown for unmatched flavor.", "fr": "Découvrez les pommes locales du Québec, cultivées avec soin pour une saveur incomparable."}', '{"en": "apples", "fr": "pommes"}', null, 'true', '0', '2025-04-26 10:24:35.922418+00', '2025-04-26 10:24:35.922418+00', 'false'), ('2306a97f-0a98-45dc-9311-15cdccfc4cf4', 'c75de2cb-9f5e-41a2-a27c-0690e867e8aa', '{"en": "Candles and Home Ambiance", "fr": "Bougies et ambiances"}', '{"en": "Create a cozy atmosphere with Quebec-made candles and home ambiance accessories.", "fr": "Créez une atmosphère chaleureuse avec des bougies artisanales et accessoires d''ambiance fabriqués au Québec."}', '{"en": "candles-and-home-ambiance", "fr": "bougies-et-ambiances"}', null, 'true', '0', '2025-04-26 14:00:26.346863+00', '2025-04-26 14:08:25.956127+00', 'false'), ('23ef662b-3216-4c21-b9ee-23756716c24f', '4cd35b53-8ce2-4733-9087-8f4d263e9469', '{"en": "Local exotic fruits", "fr": "Fruits exotiques locaux"}', '{"en": "Discover local exotic fruits, grown here for a unique and refreshing taste.", "fr": "Découvrez des fruits exotiques locaux, cultivés ici pour un goût unique et rafraîchissant."}', '{"en": "local-exotic-fruits", "fr": "fruits-exotiques-locaux"}', null, 'true', '0', '2025-04-26 10:51:07.186157+00', '2025-04-26 10:51:07.186157+00', 'false'), ('26097817-d298-416a-ac5b-362e5e4596ca', null, '{"en": "Maple Products", "fr": "Produits de l’érable"}', '{"en": "Discover Quebec maple products: pure syrup, candy, butter, condiments, and artisanal goods made locally with care.", "fr": "Découvrez l’univers de l’érable du Québec : sirop pur, bonbons, beurre, condiments et produits artisanaux faits localement."}', '{"en": "maple-products", "fr": "produits-de-lerable"}', null, 'true', '-1', '2025-04-30 23:50:02.338488+00', '2025-04-30 23:50:02.338488+00', 'false'), ('2c73fe0d-d41c-4714-8dee-2097743c1587', 'cd081c43-702a-45d7-82e6-1fc23f567915', '{"en": "Quebec Sparkling Wines", "fr": "Vins mousseux du Québec"}', '{"en": "Discover Quebec sparkling wines, locally crafted with care for festive and memorable moments.", "fr": "Découvrez les vins mousseux du Québec, élaborés localement avec soin pour des moments festifs et inoubliables."}', '{"en": "quebec-sparkling-wines", "fr": "vins-mousseux-du-quebec"}', null, 'true', '0', '2025-04-26 11:28:05.284253+00', '2025-04-26 11:28:05.284253+00', 'false'), ('2d3fa4b5-4a41-490b-9768-da51a31941f2', '4cd35b53-8ce2-4733-9087-8f4d263e9469', '{"en": "Organic Fruits", "fr": "Fruits bio"}', '{"en": "Enjoy local organic fruits from Quebec, grown without chemicals for pure flavor.", "fr": "Dégustez des fruits bio locaux du Québec, cultivés sans produits chimiques pour une saveur pure."}', '{"en": "organic-fruits", "fr": "fruits-bio"}', null, 'true', '0', '2025-04-26 10:51:41.755078+00', '2025-04-26 10:51:41.755078+00', 'false'), ('31933d94-c522-4350-96fd-00dd17e68d57', 'c3b9f610-7c2a-4316-a17b-dff4bba80183', '{"en": "Carrots", "fr": "Carottes"}', '{"en": "Discover Quebec carrots, crunchy, sweet, and carefully grown by local farmers.", "fr": "Découvrez des carottes du Québec croquantes, sucrées et cultivées avec soin localement."}', '{"en": "carrots", "fr": "carottes"}', null, 'true', '0', '2025-04-26 10:59:24.16951+00', '2025-04-26 10:59:24.16951+00', 'false'), ('333f9bcf-e336-454a-899c-0fa9e7665ae1', 'c3b9f610-7c2a-4316-a17b-dff4bba80183', '{"en": "Organic Vegetables", "fr": "Légumes Bio"}', '{"en": "Discover Quebec organic vegetables, grown without chemicals for exceptional freshness and flavor.", "fr": "Découvrez des légumes bio du Québec, cultivés sans produits chimiques pour une fraîcheur exceptionnelle."}', '{"en": "organic-vegetables", "fr": "legumes-bio"}', null, 'true', '0', '2025-04-26 11:05:18.249164+00', '2025-04-26 11:05:18.249164+00', 'false'), ('35fa19b1-8b64-4e02-ad94-f5e064dba1fe', 'c3b9f610-7c2a-4316-a17b-dff4bba80183', '{"en": "Sweet Corn", "fr": "Maïs sucré"}', '{"en": "Enjoy Quebec sweet corn, tender, sweet, and a must-have summer favorite.", "fr": "Profitez du maïs sucré du Québec, tendre, sucré et incontournable de l''été."}', '{"en": "sweet-corn", "fr": "mais-sucre"}', null, 'true', '0', '2025-04-26 11:02:27.180604+00', '2025-04-26 11:02:27.180604+00', 'false'), ('384ba6d2-8f94-42ca-accd-fa10f6de1dd6', '899dd0d0-d038-4507-a083-b84dd0d8e72c', '{"en": "Artisan Frozen Meals", "fr": "Repas surgelés artisanaux"}', '{"en": "Discover Quebec artisan frozen meals, ready-to-enjoy and crafted for everyday convenience.", "fr": "Découvrez des repas surgelés artisanaux du Québec, prêts à savourer en toute simplicité."}', '{"en": "artisan-frozen-meals", "fr": "repas-surgeles-artisanaux"}', null, 'true', '0', '2025-04-26 11:16:43.701589+00', '2025-04-26 11:16:43.701589+00', 'false'), ('394cf2ee-133e-4c80-b8ce-5949d262ecd1', 'cd081c43-702a-45d7-82e6-1fc23f567915', '{"en": "Local Spirits", "fr": "Spiritueux locaux"}', '{"en": "Enjoy Quebec local spirits, carefully distilled for an authentic and refined taste.", "fr": "Appréciez des spiritueux locaux du Québec, distillés avec soin pour un goût authentique et raffiné."}', '{"en": "local-spirits", "fr": "spiritueux-locaux"}', null, 'true', '0', '2025-04-26 11:24:25.148649+00', '2025-04-26 11:24:25.148649+00', 'false'), ('3a53425a-f51a-4d0f-80a6-99ac25ba789f', '90bd2019-c6c2-4e43-82fa-71bb83f7e088', '{"en": "Wellness Products", "fr": "Produits pour le bien-être"}', '{"en": "Wellness products made in Quebec: essential oils, therapeutic cushions, natural sprays, and handmade incense to promote daily relaxation and balance.", "fr": "Produits pour le bien-être faits au Québec : huiles essentielles, coussins thérapeutiques, brumes naturelles et encens artisanaux pour favoriser relaxation et équilibre au quotidien."}', '{"en": "wellness-products", "fr": "produits-pour-le-bien-etre"}', null, 'true', '0', '2025-04-26 14:16:05.807484+00', '2025-04-26 14:16:05.807484+00', 'false'), ('40136620-2731-47ff-af7f-a35c9eafb227', null, '{"en": "Clothes", "fr": "Vêtements"}', '{"en": "Discover unique clothing locally designed with style and passion.", "fr": "Découvrez des vêtements uniques, conçus localement avec style et passion."}', '{"en": "clothes", "fr": "vetements"}', null, 'true', '-1', '2025-04-26 09:45:11.592851+00', '2025-04-26 09:45:11.592851+00', 'false'), ('40233eec-240c-4027-9cfe-35a6a382bdc2', 'cd081c43-702a-45d7-82e6-1fc23f567915', '{"en": "Non-Alcoholic Beers", "fr": "Bières sans alcool"}', '{"en": "Enjoy Quebec non-alcoholic beers, a tasty option for those who prefer a lighter experience.", "fr": "Profitez des bières sans alcool du Québec, une option savoureuse pour ceux qui préfèrent une expérience légère."}', '{"en": "non-alcoholic-beers", "fr": "bieres-sans-alcool"}', null, 'true', '0', '2025-04-26 11:28:40.821515+00', '2025-04-26 11:28:40.821515+00', 'false'), ('43076b50-21dd-4cc5-b19b-9460dc286f57', '26097817-d298-416a-ac5b-362e5e4596ca', '{"en": "Pure Maple Syrup", "fr": "Sirop d’érable pur"}', '{"en": "Enjoy 100% pure maple syrup from Quebec in golden, amber or dark varieties, perfect for pancakes, waffles, marinades and desserts.", "fr": "Savourez du sirop d’érable 100 % pur du Québec, ambré, doré ou foncé, parfait pour crêpes, gaufres, marinades et desserts."}', '{"en": "pure-maple-syrup", "fr": "sirop-derable-pur"}', null, 'true', '0', '2025-04-30 23:51:28.936687+00', '2025-04-30 23:51:28.936687+00', 'false'), ('44c79362-389e-4760-ae01-a562129c8a10', 'cd081c43-702a-45d7-82e6-1fc23f567915', '{"en": "Quebec Ciders", "fr": "Cidres du Québec"}', '{"en": "Savor Quebec artisanal ciders, made with local apples for a fresh and fruity taste.", "fr": "Savourez des cidres artisanaux du Québec, préparés avec des pommes locales pour un goût frais et fruité."}', '{"en": "quebec-ciders", "fr": "cidres-du-quebec"}', null, 'true', '0', '2025-04-26 11:29:16.341349+00', '2025-04-26 11:29:16.341349+00', 'false'), ('49161133-d195-4325-b064-3df7addc4094', '73be5cb8-70cc-45a7-bf90-8cbd9a8d878b', '{"en": "Baguettes and European Breads", "fr": "Baguettes et pains européens"}', '{"en": "Savor Quebec baguettes and European breads, crispy, fresh, and locally crafted.\\n\\n", "fr": "Savourez des baguettes et pains européens du Québec, croustillants et faits localement."}', '{"en": "baguettes-and-european-breads", "fr": "baguettes-et-pains-europeens"}', null, 'true', '0', '2025-04-26 11:12:04.685165+00', '2025-04-26 11:12:04.685165+00', 'false'), ('49697d77-7f58-4324-9e82-7c2c78136327', '73be5cb8-70cc-45a7-bf90-8cbd9a8d878b', '{"en": "Sweet Bakery Products", "fr": "Produits sucrés de boulangerie"}', '{"en": "Indulge in Quebec sweet bakery treats, perfect for your special dessert moments.", "fr": "Régalez-vous avec des douceurs sucrées du Québec, parfaites pour vos moments gourmands."}', '{"en": "sweet-bakery-products", "fr": "produits-sucres-de-boulangerie"}', null, 'true', '0', '2025-04-26 11:13:01.123